// src/components/InformationComponent/TransactionList/TransactionListItem/RefundInfoModal/RefundInfoModal.jsx

import React, { useState } from 'react';
import { createPortal } from 'react-dom';
import styles from './RefundInfoModal.module.scss';
import { requestRefundApi } from '../../../../../services/booking/booking.ts'; 
import { FaMoneyCheckAlt, FaTimes, FaChevronDown, FaCheckCircle } from 'react-icons/fa';

const BANK_LIST = [
    { code: 'VCB', name: 'Vietcombank', shortName: 'VCB', bin: '970436', color: '#0c8e57', logo: 'https://cdn.haitrieu.com/wp-content/uploads/2022/02/Logo-Vietcombank.png' },
    { code: 'VTB', name: 'VietinBank', shortName: 'VTB', bin: '970415', color: '#003da5', logo: 'data:image/png;base64,' },
    { code: 'BIDV', name: 'BIDV', shortName: 'BIDV', bin: '970418', color: '#a1272f', logo: 'data:image/png;base64,' },
    { code: 'AGR', name: 'Agribank', shortName: 'AGR', bin: '970405', color: '#0066b2', logo: 'data:image/png;base64,' },
    { code: 'ACB', name: 'ACB', shortName: 'ACB', bin: '970416', color: '#00a7d0', logo: 'data:image/jpeg;base64,' },
    { code: 'TCB', name: 'Techcombank', shortName: 'TCB', bin: '970407', color: '#e91c23', logo: 'data:image/png;base64,' },
    { code: 'VPB', name: 'VPBank', shortName: 'VPB', bin: '970432', color: '#1e5c96', logo: 'data:image/jpeg;base64,' },
    { code: 'HDB', name: 'HDBank', shortName: 'HDB', bin: '970437', color: '#f4a920', logo: 'data:image/png;base64,' },
    { code: 'LPB', name: 'LienVietPostBank', shortName: 'LPB', bin: '970449', color: '#e84e1f', logo: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTtgGDepFmS97nx0h77eIWM5hAEhP22sUyvew&s' },
    { code: 'SHB', name: 'SHB', shortName: 'SHB', bin: '970443', color: '#ff6b35', logo: 'https://cdn.haitrieu.com/wp-content/uploads/2022/02/Logo-SHB.png' },
    { code: 'TPB', name: 'TPBank', shortName: 'TPB', bin: '970423', color: '#6f31a8', logo: 'https://cdn.haitrieu.com/wp-content/uploads/2022/02/Logo-TPBank.png' },
    { code: 'SEAB', name: 'SeaBank', shortName: 'SEAB', bin: '970440', color: '#ff9500', logo: 'data:image/png;base64,' },
    { code: 'MB', name: 'MB Bank', shortName: 'MB', bin: '970422', color: '#e30613', logo: 'https://rubicmarketing.com/wp-content/uploads/2022/11/y-nghia-logo-mb-bank-2.jpg' },
    { code: 'MSB', name: 'MSB', shortName: 'MSB', bin: '970426', color: '#c41e3a', logo: 'data:image/jpeg;base64,' },
    { code: 'VIB', name: 'VIB', shortName: 'VIB', bin: '970441', color: '#ffc20e', logo: 'data:image/png;base64,' },
    { code: 'NCB', name: 'NCB', shortName: 'NCB', bin: '970419', color: '#00308e', logo: 'data:image/png;base64,' },
    { code: 'SAC', name: 'Sacombank', shortName: 'SAC', bin: '970403', color: '#1e6dd2', logo: 'data:image/png;base64,' },
    { code: 'EXIM', name: 'Eximbank', shortName: 'EXIM', bin: '970431', color: '#007ac3', logo: 'data:image/png;base64,' },
];

const getBankLogo = (bank) => (bank.logo || '');

// Helper: resolve a bank from code, shortName, or full name (case-insensitive)
const resolveBank = (value) => {
    if (!value) return null;
    const v = String(value).trim();
    if (!v) return null;
    const upper = v.toUpperCase();
    return (
        BANK_LIST.find(b => b.code.toUpperCase() === upper) ||
        BANK_LIST.find(b => (b.shortName || '').toUpperCase() === upper) ||
        BANK_LIST.find(b => (b.name || '').toUpperCase() === upper)
    ) || null;
};

// Helper: map to standardized VietQR bank display name (uppercase)
const getVietQRBankName = (bankOrCode) => {
    if (!bankOrCode) return '';
    const bank = typeof bankOrCode === 'string' ? resolveBank(bankOrCode) : bankOrCode;
    const code = (bank?.code || '').toUpperCase();
    const mapping = {
        VCB: 'VIETCOMBANK',
        VTB: 'VIETINBANK',
        BIDV: 'BIDV',
        AGR: 'AGRIBANK',
        ACB: 'ACB',
        TCB: 'TECHCOMBANK',
        VPB: 'VPBANK',
        HDB: 'HDBANK',
        LPB: 'LIENVIETPOSTBANK',
        SHB: 'SHB',
        TPB: 'TPBANK',
        SEAB: 'SEABANK',
        MB: 'MBBANK',
        MSB: 'MSB',
        VIB: 'VIB',
        NCB: 'NCB',
        SAC: 'SACOMBANK',
        EXIM: 'EXIMBANK',
    };
    return mapping[code] || (bank?.name || '').toUpperCase();
};

const handleLogoError = (event) => {
    const fallbackEl = event.currentTarget.nextElementSibling;
    if (fallbackEl) fallbackEl.style.display = 'flex';
    event.currentTarget.style.display = 'none';
};

const BankSelectionModal = ({ onSelect, onClose }) => {
    const handleBankClick = (bankCode) => {
        onSelect(bankCode);
        onClose();
    };

    const bankSelectionJSX = (
        <div className={styles.bankSelectOverlay} onClick={onClose}>
            <div className={styles.bankSelectContent} onClick={(e) => e.stopPropagation()}>
                <div className={styles.bankSelectHeader}>
                    <h4>Chọn Ngân hàng hưởng thụ</h4>
                    <FaTimes className={styles.closeIcon} onClick={onClose} />
                </div>
                <div className={styles.bankGrid}>
                    {BANK_LIST.map((bank) => (
                        <div
                            key={bank.code}
                            className={styles.bankCard}
                            onClick={() => handleBankClick(bank.code)}
                        >
                            <div className={styles.bankEmblem}>
                                <img
                                    src={getBankLogo(bank)}
                                    alt={bank.name}
                                    className={styles.bankLogo}
                                    loading="lazy"
                                    onError={handleLogoError}
                                />
                                <div
                                    className={styles.logoFallback}
                                    style={{ backgroundColor: bank.color }}
                                >
                                    {bank.shortName}
                                </div>
                            </div>
                            <div className={styles.bankInfo}>
                                <span className={styles.bankName}>{bank.name}</span>
                                <span className={styles.bankCode}>BIN: {bank.bin}</span>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );

    return createPortal(bankSelectionJSX, document.body);
};


// ✅ Thêm 'booking' vào props
const RefundInfoModal = ({ bookingID, booking, onClose, onBack, onRefetch }) => {
    // ✅ Chuẩn hoá giá trị ngân hàng từ booking (chấp nhận code, shortName, hoặc name)
    const initialResolvedBank = resolveBank(booking?.bank);
    // ✅ Khởi tạo state với dữ liệu sẵn có từ booking (ưu tiên lưu code chuẩn)
    const [formData, setFormData] = useState({
        accountName: booking.accountName || '',
        accountNumber: booking.accountNumber || '',
        bank: initialResolvedBank ? initialResolvedBank.code : (booking.bank || ''),
    });
    const [isProcessing, setIsProcessing] = useState(false);
    const [error, setError] = useState(null);
    const [successMessage, setSuccessMessage] = useState(null);
    const [showBankModal, setShowBankModal] = useState(false); // State quản lý modal chọn Bank

    // ✅ Tìm ngân hàng theo mã/shortName/name để hiển thị
    const selectedBank = resolveBank(formData.bank);

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };
    
    // HÀM CHỌN BANK TỪ MODAL CON
    const handleBankSelect = (bankCode) => {
        setFormData(prev => ({ ...prev, bank: bankCode }));
    };

    // HÀM XỬ LÝ ĐÓNG MODAL (dùng WS để cập nhật, không reload trang)
    const handleCloseSuccess = () => {
        if (onRefetch) onRefetch();
        onClose();
    };
    
    const handleConfirmRefund = async () => {
        setError(null);
        if (!formData.accountName || !formData.accountNumber || !formData.bank) {
            setError("Vui lòng điền đầy đủ các thông tin bắt buộc.");
            return;
        }

        setIsProcessing(true);
        try {
            // Gửi tên ngân hàng đầy đủ tới backend để phù hợp với cột bank_name
            const payload = {
                accountName: formData.accountName,
                accountNumber: formData.accountNumber,
                // Gửi tên ngân hàng chuẩn VietQR (uppercase)
                bank: getVietQRBankName(selectedBank || formData.bank),
            };
            await requestRefundApi(bookingID, payload);
            
            setSuccessMessage("Cảm ơn bạn! Yêu cầu hoàn tiền qua Ngân hàng của bạn đã thành công. Vui lòng đợi chúng tôi xử lí hoàn tiền lại.");
            
        } catch (err) { 
            console.error("Lỗi khi yêu cầu hoàn tiền Ngân hàng:", err);
            const apiError = err.response?.data?.message || "Lỗi khi gửi yêu cầu hoàn tiền.";
            setError(apiError);
        } finally {
            setIsProcessing(false);
        }
    };

        // --- JSX cho Modal Thông báo Thành công ---
        if (successMessage) {
            const successModalJSX = (
                <div className={styles.modalOverlay} onClick={onClose}>
                    <div
                        className={`${styles.modalContent} ${styles.successContent}`}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <div className={styles.successIcon}>
                            <FaCheckCircle />
                        </div>
                        <h3 className={styles.successTitle}>Thành công!</h3>
                        <p className={styles.successMessage}>{successMessage}</p>
                        <div className={styles.successActions}>
                            <button 
                                className={styles.successButton} 
                                onClick={handleCloseSuccess}
                            >
                                Đóng
                            </button>
                        </div>
                    </div>
                </div>
            );
            return createPortal(successModalJSX, document.body); 
        }

        // --- JSX cho Modal Nhập thông tin Hoàn tiền ---
        const refundInfoModalJSX = (
            <div className={styles.modalOverlay} onClick={onClose}>
                {showBankModal && (
                    <BankSelectionModal 
                        onSelect={handleBankSelect} 
                        onClose={() => setShowBankModal(false)}
                    />
                )}

                <div className={styles.modalContent} onClick={(e) => e.stopPropagation()}>
                    <div className={styles.headerSection}>
                        <div className={styles.icon}>
                            <FaMoneyCheckAlt />
                        </div>
                        <h3 className={styles.title}>Thông Tin Hoàn Tiền Ngân Hàng</h3>
                        <p className={styles.description}>Điền thông tin tài khoản để nhận tiền hoàn trả</p>
                    </div>

                    <div className={styles.formSection}>
                        <div className={styles.formGroup}>
                            <label htmlFor="accountName">Tên chủ tài khoản *</label>
                            <input 
                                type="text" 
                                id="accountName" 
                                name="accountName" 
                                value={formData.accountName} 
                                onChange={handleChange} 
                                placeholder="Nhập tên chủ tài khoản"
                                required 
                            />
                        </div>

                        <div className={styles.formGroup}>
                            <label htmlFor="accountNumber">Số tài khoản *</label>
                            <input 
                                type="text" 
                                id="accountNumber" 
                                name="accountNumber" 
                                value={formData.accountNumber} 
                                onChange={handleChange} 
                                placeholder="Nhập số tài khoản"
                                required 
                            />
                        </div>

                        <div className={styles.formGroup}>
                            <label>Ngân hàng hưởng thụ *</label>
                            <div className={styles.bankSelectTrigger} onClick={() => setShowBankModal(true)}>
                                {selectedBank ? (
                                    <div className={styles.selectedBankInfo}>
                                        <div className={styles.bankEmblem}>
                                            <img
                                                src={getBankLogo(selectedBank)}
                                                alt={selectedBank.name}
                                                className={styles.bankLogo}
                                                onError={handleLogoError}
                                            />
                                            <div
                                                className={styles.logoFallback}
                                                style={{ backgroundColor: selectedBank.color }}
                                            >
                                                {selectedBank.shortName}
                                            </div>
                                        </div>
                                        <div className={styles.selectedBankText}>
                                            <span className={styles.bankName}>{selectedBank.name}</span>
                                            <span className={styles.bankCode}>BIN: {selectedBank.bin}</span>
                                        </div>
                                    </div>
                                ) : (
                                    <span className={styles.placeholder}>Chọn ngân hàng...</span>
                                )}
                                <FaChevronDown />
                            </div>
                            <input type="hidden" name="bank" value={formData.bank} /> 
                        </div>

                        {error && <div className={styles.error}>{error}</div>}
                    </div>

                    <div className={styles.buttonGroup}>
                        <button className={styles.btnSecondary} onClick={onBack} disabled={isProcessing}>Hủy</button>
                        <button 
                            className={styles.btnPrimary} 
                            onClick={handleConfirmRefund} 
                            disabled={isProcessing}
                        >
                            {isProcessing ? 'Đang xử lý...' : 'Xác nhận'}
                        </button>
                    </div>
                </div>
            </div>
        );
    
    return createPortal(refundInfoModalJSX, document.body); 
};

export default RefundInfoModal;